  'Social Work Practice with Communities and Organizations',
  'This course prepares BSW students for ethical, justice-centered generalist practice with communities and organizations. Students learn to engage constituencies, assess assets and power, organize collective action, build coalitions, analyze policy, develop programs, understand organizations, support change, manage resources, evaluate results, and communicate strategically. A community-engaged project integrates the full macro-practice cycle.',
  $swcojson${"slug": "social-work-practice-with-communities-and-organizations", "title": "Social Work Practice with Communities and Organizations", "description": "This course prepares BSW students for ethical, justice-centered generalist practice with communities and organizations. Students learn to engage constituencies, assess assets and power, organize collective action, build coalitions, analyze policy, develop programs, understand organizations, support change, manage resources, evaluate results, and communicate strategically. A community-engaged project integrates the full macro-practice cycle.", "topics": [{"id": "2a5db04c-9264-4e1b-a43a-818618b19e6c", "type": "topic", "title": "Macro Social Work and Generalist Practice", "description": "Locate community and organizational change within generalist social work and connect macro conditions to individual and family well-being.", "children": [{"id": "fb82dcbe-b074-46d7-ac40-b39612eb7941", "type": "subtopic", "title": "Levels and integration", "children": [{"id": "2f91efe8-0603-4768-80c0-7c2b82c6dc9b", "type": "concept", "title": "Person-in-environment and ecosystems perspectives"}, {"id": "82b5b62c-70bd-42be-a804-a5260b1c4c44", "type": "concept", "title": "Direct-service patterns as organizational/policy evidence"}, {"id": "b7f0180e-9de9-4935-a28d-9a77891a92d6", "type": "concept", "title": "Case-to-cause and cause-to-case thinking"}], "description": "Students see micro, mezzo, and macro practice as mutually shaping."}, {"id": "11a7edd3-3839-4b0c-9339-8398cf7277de", "type": "subtopic", "title": "Macro practitioner roles", "children": [{"id": "f521b7da-8e41-4ba0-b165-f1eae6eb7fe8", "type": "concept", "title": "Organizer, planner, administrator, advocate, evaluator, policy practitioner"}, {"id": "78aa2fbb-d1aa-4c29-9bda-57a415143d51", "type": "concept", "title": "Facilitator, coalition builder, fundraiser, communicator, and leader"}, {"id": "a95e3916-3f0b-40ef-a872-bf7665c464be", "type": "concept", "title": "Inside, outside, and boundary-spanning roles"}], "description": "The point is a practical map of ways social workers create change."}, {"id": "b7786f6a-8824-4a40-855a-0c6ec7f0798c", "type": "subtopic", "title": "Competency and reflection", "children": [{"id": "c11b607d-a978-4935-a282-43f501d5826a", "type": "concept", "title": "CSWE engagement, assessment, intervention, evaluation, and policy competencies"}, {"id": "833d74f0-48ef-41e3-b2cb-6f61ceed2f86", "type": "concept", "title": "Use of self, power, bias, privilege, and accountability"}, {"id": "370e976e-6910-480b-b2b4-0b42519b1907", "type": "concept", "title": "Supervision, consultation, and lifelong learning"}], "description": "Students identify positionality, limits, and growth needs."}]}, {"id": "c61b8041-e67f-4896-95ba-0ba63e40c227", "type": "topic", "title": "Community Theory, Power, and Social Structure", "description": "Understand communities as places, identities, relationships, institutions, and contested systems of power.", "children": [{"id": "8e148be3-60b8-45ca-aceb-a9fca8266123", "type": "subtopic", "title": "Meanings of community", "children": [{"id": "cfd202a3-5deb-420e-86df-eb4824d22d27", "type": "concept", "title": "Membership, belonging, boundaries, and place"}, {"id": "9d4d0500-3db0-4a62-802e-7594ed614097", "type": "concept", "title": "Formal/informal institutions and networks"}, {"id": "1ca31203-0717-4ce2-baf0-abc2ed17bc48", "type": "concept", "title": "Community narratives and contested representation"}], "description": "Students compare geographic, identity, interest, virtual, and relational communities."}, {"id": "81805547-5a70-4732-9918-b984dd1ef2c8", "type": "subtopic", "title": "Power and oppression", "children": [{"id": "1bb7afe3-de80-44b9-b78d-9143a66f8811", "type": "concept", "title": "Visible, hidden, structural, and cultural power"}, {"id": "4c8a836b-d8eb-4d60-83b9-5f7edb0381a9", "type": "concept", "title": "Racism, colonialism, class, gender, disability, and intersectionality"}, {"id": "a83cc068-29ee-4e31-84ef-572d66b10b37", "type": "concept", "title": "Privilege, exclusion, resistance, and collective agency"}], "description": "The goal is to identify who sets agendas, controls resources, and defines legitimate knowledge."}, {"id": "653e6563-bfaa-44a8-a31d-24d8cfcbc63d", "type": "subtopic", "title": "Community change theory", "children": [{"id": "daee1842-3203-4a90-b7ec-222b9fb8cbbf", "type": "concept", "title": "Social capital, collective efficacy, empowerment, and critical consciousness"}, {"id": "646a5aab-dd13-4173-87a0-ae19285e5191", "type": "concept", "title": "Conflict, pluralist, systems, and political-economy perspectives"}, {"id": "2113d47e-fe9a-4db2-a0d7-4ba83cbc5372", "type": "concept", "title": "Social movements and policy feedback"}], "description": "Students use theory to anticipate action and response."}]}, {"id": "2edb3b2f-c268-4c64-8ee0-abfd64f604a2", "type": "topic", "title": "Ethics, Human Rights, and Anti-Oppressive Macro Practice", "description": "Apply social work values to community and organizational decisions where rights, resources, participation, and risk are unevenly distributed.", "children": [{"id": "c7390c34-1aae-4776-a7ca-2086ac6f6ec6", "type": "subtopic", "title": "Ethical foundations", "children": [{"id": "6add02d4-f11e-4bbe-93ef-9bb008b28bcc", "type": "concept", "title": "Service, social justice, dignity, relationships, integrity, and competence"}, {"id": "f345dc77-460a-4959-a831-8c3f4d2629df", "type": "concept", "title": "Conflicts of interest, informed participation, and transparency"}, {"id": "0c2ccd82-84e9-4cc5-9ca6-1ebd50f79b18", "type": "concept", "title": "Professional boundaries and political activity"}], "description": "Students translate the NASW Code into macro choices."}, {"id": "04cd2cf4-1001-4e21-8765-e2b57230e8d2", "type": "subtopic", "title": "Human rights and justice", "children": [{"id": "baf7c94e-a09b-441e-8f6a-0ab419e48f02", "type": "concept", "title": "Civil, political, economic, social, cultural, and disability rights"}, {"id": "84cb57c1-4583-4b6f-a582-0dcf9e7b3ce5", "type": "concept", "title": "Distribution, recognition, participation, and repair"}, {"id": "e2ac89c0-4fe4-4955-940b-10bbe5bedc90", "type": "concept", "title": "Intergenerational and environmental justice"}], "description": "The point is linking local practice to social, racial, economic, and environmental justice."}, {"id": "5e8c8cfb-2638-4103-8233-9b2810d6900d", "type": "subtopic", "title": "Anti-oppressive accountability", "children": [{"id": "36d9a844-10be-4749-841b-c4dd00ca8885", "type": "concept", "title": "Community expertise and shared power"}, {"id": "630eff47-5f76-4e82-9471-b374824b6e57", "type": "concept", "title": "Language access, accessibility, and compensation"}, {"id": "16ef3dfb-e07b-4c95-8f40-3a4ac20270ca", "type": "concept", "title": "Data harm, surveillance, retaliation, and do-no-harm planning"}], "description": "Students avoid extractive or savior-oriented practice."}]}, {"id": "564c4b81-8ed0-4ef7-965a-09e42cc3a05f", "type": "topic", "title": "Community Engagement and Relationship Building", "description": "Build trust and reciprocal relationships before defining problems or proposing interventions.", "children": [{"id": "986e0705-0b1b-4a32-9da9-00cb8653ba32", "type": "subtopic", "title": "Entry and presence", "children": [{"id": "07f6e298-9858-4681-b1e5-f87de9c4ce7f", "type": "concept", "title": "Stakeholder permission and introductions"}, {"id": "eaadf242-ffa4-42c4-b890-bea66958ae65", "type": "concept", "title": "History, prior harms, expectations, and readiness"}, {"id": "5e6336c6-b642-481f-a079-580daba87fcc", "type": "concept", "title": "Reliability, listening, reciprocity, and visibility"}], "description": "Students learn respectful entry into communities and organizations."}, {"id": "5f81e5ea-20af-41ac-b0b8-397ad68fd342", "type": "subtopic", "title": "Engagement methods", "children": [{"id": "63fb644f-4bf9-4475-b42b-b1bac19d103c", "type": "concept", "title": "One-to-one conversations, listening sessions, town halls, and outreach"}, {"id": "6dadd6ae-d358-428c-80bd-4161b2899fcc", "type": "concept", "title": "Language, disability, schedule, childcare, transport, and digital access"}, {"id": "a4497fd1-32ed-4fb4-86c7-7d518a343d68", "type": "concept", "title": "Reaching excluded and less-visible constituencies"}], "description": "The goal is broad and meaningful participation."}, {"id": "d824098a-1a3f-4791-968f-111dc10842bb", "type": "subtopic", "title": "Trust and conflict", "children": [{"id": "dc525523-2be6-461f-87ef-50474ab09f30", "type": "concept", "title": "Trauma-informed and culturally responsive engagement"}, {"id": "d324a749-ee09-4f60-9a4d-3464d9770ebf", "type": "concept", "title": "Repair, apology, confidentiality, and rumor response"}, {"id": "4bb432d9-73db-4060-bd7a-9459614db00e", "type": "concept", "title": "Boundaries, safety, and exit/transition planning"}], "description": "Students sustain relationships amid disagreement."}]}, {"id": "5cfc44b6-254e-4dcb-b7f7-90eea4d1071a", "type": "topic", "title": "Participatory Community Assessment and Asset Mapping", "description": "Co-produce an evidence-rich understanding of community strengths, priorities, inequities, and opportunities.", "children": [{"id": "2ad76bc0-52b9-44fe-b62d-2eb8e1b70ae3", "type": "subtopic", "title": "Assessment design", "children": [{"id": "24d4c540-8b31-4da4-9340-ab4721de5fe0", "type": "concept", "title": "Community-defined questions and indicators"}, {"id": "40c706dd-a09b-441e-9d21-871c76182957", "type": "concept", "title": "Assets, needs, risks, protective factors, and history"}, {"id": "3e64a6ad-31b0-4b98-8b8f-43f7e0862307", "type": "concept", "title": "Sampling, inclusion, consent, and ethics"}], "description": "Students clarify purpose, users, questions, and decision points."}, {"id": "6a51247c-46ab-45e3-8b43-41bd89af501a", "type": "subtopic", "title": "Methods and data", "children": [{"id": "d5509ebb-d90d-4519-b8cb-59c4f2dd5732", "type": "concept", "title": "Interviews, focus groups, surveys, observation, and administrative data"}, {"id": "9ee0aa56-de12-4df9-8245-6c2e7e8e27db", "type": "concept", "title": "Asset maps, service maps, GIS, PhotoVoice, and community walks"}, {"id": "b7b32730-6658-4ced-bf5e-838cdb4fa108", "type": "concept", "title": "Disaggregation, missingness, bias, and data sovereignty"}], "description": "The point is triangulation without privileging only professional data."}, {"id": "1dc3b703-94b8-413d-ab75-e184868de83d", "type": "subtopic", "title": "Sensemaking and priority setting", "children": [{"id": "aab67ee2-d43d-42a2-866c-5d7f11c4aa7a", "type": "concept", "title": "Validation sessions and member checking"}, {"id": "3bad2357-6d68-4e6a-975f-78c250498af5", "type": "concept", "title": "Root causes versus symptoms"}, {"id": "0ca340d1-fab4-432c-8326-15587c505cf1", "type": "concept", "title": "Prioritization by importance, changeability, equity, and readiness"}], "description": "Students return findings to the community for interpretation."}]}, {"id": "86f96750-0b4d-4e82-a3e8-d00dec3900f2", "type": "topic", "title": "Stakeholder, Network, and Systems Analysis", "description": "Map actors, relationships, incentives, resources, and feedback that shape a community or organizational issue.", "children": [{"id": "30778625-8728-433b-b7b3-ddcdd2f3f7d5", "type": "subtopic", "title": "Stakeholder analysis", "children": [{"id": "be718173-1c75-4cf8-85a8-49e7bdc73da8", "type": "concept", "title": "Affected groups, decision makers, implementers, funders, and opposition"}, {"id": "0e546061-1c51-4f90-9723-92f65ffa24e2", "type": "concept", "title": "Power, position, salience, legitimacy, and vulnerability"}, {"id": "ff4c0ba4-d14c-4794-b9d7-1eea0a948f69", "type": "concept", "title": "Engagement strategy and accountability"}], "description": "Students move beyond lists to interests and influence."}, {"id": "5754c055-8904-4340-bd08-eb8996293098", "type": "subtopic", "title": "Network analysis", "children": [{"id": "46b6e462-cedc-4f02-b273-4d44618e40bd", "type": "concept", "title": "Formal and informal ties"}, {"id": "0ea42a49-f143-4d98-9aef-4022319a992c", "type": "concept", "title": "Resource, information, referral, and trust networks"}, {"id": "5ccdd912-ae73-46d8-b872-88be42ba98d0", "type": "concept", "title": "Centrality and isolation concepts"}], "description": "The goal is identifying connectors, gaps, brokers, and dependencies."}, {"id": "b23562cb-e131-410d-83e1-55efcc0bb5da", "type": "subtopic", "title": "Systems mapping", "children": [{"id": "4cf79f46-3b81-4169-b13c-0da27ef030ab", "type": "concept", "title": "Causal loops, stocks/flows, delays, and leverage points"}, {"id": "cd4bdebd-051a-4f99-a91c-cdb075c80165", "type": "concept", "title": "Policy, organizational, community, and market interactions"}, {"id": "fe4937fd-eb1d-4cca-9c98-34dcf92d4ac7", "type": "concept", "title": "Boundary choices and uncertainty"}], "description": "Students visualize dynamic causes and unintended effects."}]}, {"id": "9e0b49da-dc2c-438d-a2f7-377b0ece7426", "type": "topic", "title": "Community Organizing Strategies", "description": "Build collective power through leadership development, issue selection, membership, strategy, action, and reflection.", "children": [{"id": "fdcb6bb6-79cd-432e-8543-7f18576269c4", "type": "subtopic", "title": "Organizing traditions", "children": [{"id": "bd7fcf43-f767-4e08-885b-aca88bb82a8c", "type": "concept", "title": "Consensus versus conflict strategies"}, {"id": "b3242dee-587d-4fd9-83f8-78cac4127cc1", "type": "concept", "title": "Faith-, labor-, neighborhood-, identity-, and issue-based organizing"}, {"id": "132fa416-8ebb-4d4d-a94a-ca65a6ccbe14", "type": "concept", "title": "Online/offline and hybrid organizing"}], "description": "Students compare locality development, social planning, social action, and movement approaches."}, {"id": "98da9a75-a2f6-4d9e-8bab-daaf2e0182cf", "type": "subtopic", "title": "Campaign development", "children": [{"id": "c4684089-3d74-4560-8ebb-fb799312aa9f", "type": "concept", "title": "Issue cutting, targets, demands, and power analysis"}, {"id": "62a3dc42-b1c2-43fd-a19a-df519d2d4ce3", "type": "concept", "title": "Goals, tactics, timeline, and escalation"}, {"id": "f536779c-2f24-4017-8146-5ca5b7c62e9c", "type": "concept", "title": "Leadership ladder and member ownership"}], "description": "The point is converting a broad concern into a winnable step toward structural change."}, {"id": "4a5ef41b-ae9e-4184-afe2-9c6d145ddf17", "type": "subtopic", "title": "Action and learning", "children": [{"id": "fd68b337-a54e-459b-9bc5-56d8b2e0bcab", "type": "concept", "title": "Meetings, turnout, petitions, direct action, and negotiation"}, {"id": "925d40a5-4b72-4f5b-a1ba-2464969d4472", "type": "concept", "title": "Legal/safety planning and de-escalation"}, {"id": "166dd536-38fd-460a-b3cd-ff7f6bf37a43", "type": "concept", "title": "Debrief, evaluation, celebration, and next cycle"}], "description": "Students prepare ethical, disciplined collective action."}]}, {"id": "cb8ddd96-59b6-4072-922d-eaa32142386b", "type": "topic", "title": "Community Development and Place-Based Practice", "description": "Strengthen community capacity, assets, institutions, opportunity, and control over development.", "children": [{"id": "45d15157-0d8d-4aa4-8d17-bd9a27696358", "type": "subtopic", "title": "Asset-based development", "children": [{"id": "71e8befc-d941-4f46-b70d-0a1ff39fe531", "type": "concept", "title": "Individual, association, institution, physical, cultural, and economic assets"}, {"id": "27958a0e-8db8-4af2-a3cb-cc269b6640bf", "type": "concept", "title": "Resident leadership and mutual aid"}, {"id": "2653ba7a-5584-47e3-b124-f9823f587307", "type": "concept", "title": "Capacity building and local ownership"}], "description": "Students identify capacities without denying structural deprivation."}, {"id": "9bdf81ff-0028-4453-baa3-1940e72cf517", "type": "subtopic", "title": "Place and economic development", "children": [{"id": "c043bd74-44a2-427a-ac3e-a59823556296", "type": "concept", "title": "Housing, land use, transport, food, schools, health, and public space"}, {"id": "a6cb27d9-4efe-4bf8-9915-ea4362ee97e2", "type": "concept", "title": "Workforce, small business, cooperatives, and community wealth"}, {"id": "5bfabbfe-274f-4ed7-9eab-04c9a18677e6", "type": "concept", "title": "Gentrification, displacement, and community benefits"}], "description": "The goal is equitable improvement rather than displacement."}, {"id": "2f59f0eb-f473-4b54-9242-4f8383420aed", "type": "subtopic", "title": "Sustainability and resilience", "children": [{"id": "dbef8e41-f471-46b8-bebe-0586b4e1e64b", "type": "concept", "title": "Climate adaptation and environmental health"}, {"id": "bbd5ec60-61bf-4154-ad3c-7a433038abf0", "type": "concept", "title": "Disaster preparedness, recovery, and mutual aid"}, {"id": "855ff927-e26d-403b-aa6d-17a300d6d7e7", "type": "concept", "title": "Institutionalization without loss of community control"}], "description": "Students plan for shocks and long-term stewardship."}]}, {"id": "4018d9d0-7bfd-439a-84fd-94c94b4473cf", "type": "topic", "title": "Coalition Building and Collaborative Governance", "description": "Create and sustain cross-sector coalitions with shared purpose, equitable governance, and measurable action.", "children": [{"id": "94c051c5-64c9-4087-ae7b-81609b42d85b", "type": "subtopic", "title": "Coalition formation", "children": [{"id": "ea485864-a067-4989-86cf-e2cbcdec0908", "type": "concept", "title": "Issue fit, membership, readiness, and convening"}, {"id": "bb328a76-18c4-4e11-b197-910ce527c6f1", "type": "concept", "title": "Common agenda and theory of change"}, {"id": "663db4ce-f331-4043-98f9-c0356fc49088", "type": "concept", "title": "Member value proposition and resource commitments"}], "description": "Students assess whether collaboration adds value."}, {"id": "2eac3abe-608a-474b-b92b-6a61404654ca", "type": "subtopic", "title": "Governance and participation", "children": [{"id": "8775a402-e7f8-42fa-a315-28d5802fe625", "type": "concept", "title": "Roles, committees, facilitation, voting/consensus, and conflict processes"}, {"id": "0244c0d8-3b25-458e-95d6-4039053bf459", "type": "concept", "title": "Representation, compensation, accessibility, and language justice"}, {"id": "d731c5e0-eb09-4b77-8e80-499e348a7c63", "type": "concept", "title": "Backbone support and distributed leadership"}], "description": "The point is clear, fair decision making."}, {"id": "e4241630-9710-4744-8711-da9e88542869", "type": "subtopic", "title": "Performance and sustainability", "children": [{"id": "0260e688-f030-446d-bdde-3c466b7a8268", "type": "concept", "title": "Participation, trust, implementation, outcomes, and equity"}, {"id": "f62d430f-56f6-47d3-9fe7-777a4fceaf4b", "type": "concept", "title": "Communication and accountability to constituencies"}, {"id": "0da2e071-1437-4241-94fb-8084b731555f", "type": "concept", "title": "Funding, succession, adaptation, and responsible closure"}], "description": "Students track both relationships and results."}]}, {"id": "08a4cff5-573b-461d-8296-6ebbeef74ed1", "type": "topic", "title": "Advocacy, Campaigns, and Civic Participation", "description": "Influence public attitudes, administrative decisions, budgets, policies, and institutional practices through ethical advocacy.", "children": [{"id": "a791a54a-cd37-4833-81fe-1dcf94153cc8", "type": "subtopic", "title": "Advocacy strategy", "children": [{"id": "839fe73e-fb13-4481-a293-de44c775311f", "type": "concept", "title": "Legislative, regulatory, budget, legal, electoral, and organizational venues"}, {"id": "563c9edc-de40-47f7-9b69-6d3c7cfd4d05", "type": "concept", "title": "Insider/outsider and grasstops/grassroots tactics"}, {"id": "d8e34885-ec8b-4de5-8b60-f3ef8ca2f8fc", "type": "concept", "title": "Power, timing, opposition, and coalition alignment"}], "description": "Students specify the decision, target, constituency, and theory of influence."}, {"id": "67af90a5-3ad5-4aea-b999-6371c2d7eb89", "type": "subtopic", "title": "Tactics and communication", "children": [{"id": "021fd630-a70d-4dca-b879-95732605ac65", "type": "concept", "title": "Meetings, testimony, comments, letters, petitions, scorecards, and media"}, {"id": "f5c62333-8385-4843-bff4-9e1c8f84501e", "type": "concept", "title": "Story, evidence, values, messenger, and ask"}, {"id": "29784762-f740-4e0c-9379-fc19b1b23d99", "type": "concept", "title": "Digital organizing, accessibility, and misinformation response"}], "description": "The goal is action matched to context."}, {"id": "3b5b5ae0-0f1d-49b8-954a-c0a3cd8231ec", "type": "subtopic", "title": "Civic participation", "children": [{"id": "80a05b4c-6731-478e-bd64-89b78d2552b9", "type": "concept", "title": "Voter education/engagement within legal and ethical boundaries"}, {"id": "1f1051da-95c2-4f70-8266-f9cad556f73a", "type": "concept", "title": "Participatory budgeting and public hearings"}, {"id": "2cdd47dd-e5dc-4e64-9224-fa96779a77da", "type": "concept", "title": "Boards, commissions, advisory councils, and community oversight"}], "description": "Students expand meaningful democratic involvement."}]}, {"id": "ab316519-0c18-4304-acb1-9e4eaa6d3a4a", "type": "topic", "title": "Policy Practice and Structural Change", "description": "Analyze how policy creates community conditions and develop feasible, justice-centered policy alternatives.", "children": [{"id": "e551eb1f-662a-440c-9ef7-1942bed69e65", "type": "subtopic", "title": "Policy analysis", "children": [{"id": "3078d4ab-6755-41b5-8380-fd26b2dbaf0a", "type": "concept", "title": "Problem definition, history, eligibility, benefits, administration, and financing"}, {"id": "c1a9b760-fae6-499a-9bcb-60fecec770c3", "type": "concept", "title": "Winners, losers, administrative burden, and unintended effects"}, {"id": "144cafed-2c99-403e-b470-cb0edf294ed2", "type": "concept", "title": "Evidence, equity, rights, feasibility, and implementation"}], "description": "Students connect policy design to lived experience and service access."}, {"id": "508ed5e0-59b1-417a-a0c1-720d9806295e", "type": "subtopic", "title": "Policy formulation", "children": [{"id": "4a176cd4-d6dc-410d-bdc4-ce2dc0e24122", "type": "concept", "title": "Goals, options, instruments, and criteria"}, {"id": "8dabbee0-704b-425d-8541-5eedd5202b94", "type": "concept", "title": "Universal, targeted, and targeted-universal approaches"}, {"id": "de05fe65-051e-4126-b6c6-2ca43123cf7f", "type": "concept", "title": "Drafting recommendations and implementation provisions"}], "description": "The point is moving from critique to alternatives."}, {"id": "47164516-e7c3-46fc-9052-40220ccf3708", "type": "subtopic", "title": "Policy advocacy and feedback", "children": [{"id": "c30b7f49-58b4-4940-bfa1-1af6cbfd93a0", "type": "concept", "title": "Coalition and decision-maker strategy"}, {"id": "e3cbe444-9e77-4d7e-b6fd-3d166c2bdba6", "type": "concept", "title": "Rulemaking, budgets, and oversight"}, {"id": "09b563a2-004d-4b9e-b2ab-64b438342cb3", "type": "concept", "title": "Policy surveillance and community feedback"}], "description": "Students monitor adoption, implementation, and adaptation."}]}, {"id": "b7d4003e-0d56-40fa-884b-516efd727dce", "type": "topic", "title": "Program Development and Theory of Change", "description": "Design programs with communities by connecting needs and assets to mechanisms, activities, outcomes, and implementation realities.", "children": [{"id": "ea82e52d-4339-4da2-b765-4662093f77cb", "type": "subtopic", "title": "Co-design and program logic", "children": [{"id": "9fffc485-2d36-4622-93aa-186f4cdc386c", "type": "concept", "title": "Goals, population, eligibility, setting, and access"}, {"id": "aad765a4-2e51-464f-964b-d3bd79af156b", "type": "concept", "title": "Theory of change, logic model, assumptions, and context"}, {"id": "29c8df50-6eeb-48ed-a438-70aa830a09ed", "type": "concept", "title": "Evidence-informed components and cultural adaptation"}], "description": "Students define the problem and solution with intended participants."}, {"id": "2b64c11e-17b0-4f1f-a77a-0f16c4194c3c", "type": "subtopic", "title": "Implementation planning", "children": [{"id": "8c77d522-8442-4cf3-8ff1-7fe2927cd96e", "type": "concept", "title": "Workflow, staffing, partnerships, facilities, data, and technology"}, {"id": "d9c50825-4f95-45d7-a285-7537355f09e1", "type": "concept", "title": "Recruitment, retention, dosage, fidelity, and adaptation"}, {"id": "35b121eb-5a05-42c6-82a9-267deb560bba", "type": "concept", "title": "Risk, accessibility, safeguarding, and contingency"}], "description": "The goal is an operable service, not a paper program."}, {"id": "ee8ad7b1-fc40-4be4-a802-8c5dee1d54b9", "type": "subtopic", "title": "Learning plan", "children": [{"id": "c0d6a66a-33ba-4aca-9a06-2cd313041f3d", "type": "concept", "title": "Process, outcome, equity, and balancing measures"}, {"id": "5c862696-a99f-4746-84c6-7e31adeccf6b", "type": "concept", "title": "Feedback loops and improvement cycles"}, {"id": "2c940263-ad1d-482a-b894-7305b169a1e9", "type": "concept", "title": "Scale, sustainability, and exit criteria"}], "description": "Students specify how success and unintended effects will be known."}]}, {"id": "d9a0a70d-ffab-4617-bb2f-f0d1d2f8e5d6", "type": "topic", "title": "Organizational Theory, Culture, and Assessment", "description": "Understand human-service organizations as open systems shaped by mission, culture, power, environment, and resource dependence.", "children": [{"id": "9660eeb9-5216-48f2-95fe-9fc704592771", "type": "subtopic", "title": "Organizational lenses", "children": [{"id": "40860aef-c575-4685-8a36-15c1e064cc93", "type": "concept", "title": "Formal structure and informal practice"}, {"id": "6818a032-013b-483f-b667-7770e625373c", "type": "concept", "title": "Culture, climate, routines, and symbols"}, {"id": "77cae0e6-b895-4ed5-b1a9-2f875478ced0", "type": "concept", "title": "Environment, legitimacy, and resource dependence"}], "description": "Students compare bureaucratic, human-relations, political, institutional, and systems perspectives."}, {"id": "199e505f-6e0b-4159-bd5d-44332ec698d9", "type": "subtopic", "title": "Organizational assessment", "children": [{"id": "94700b1a-1c6f-48dc-921c-19a1d6683a02", "type": "concept", "title": "Mission, strategy, governance, services, workforce, finance, data, and partnerships"}, {"id": "9d587d52-fa19-47c3-a7e1-79d888d42e1d", "type": "concept", "title": "Stakeholder experience and service journey"}, {"id": "1b1d2d79-b7fd-457b-9957-ae2b918dd031", "type": "concept", "title": "Strengths, gaps, bottlenecks, risk, and equity"}], "description": "The point is a defensible diagnosis before change."}, {"id": "5f86d7e5-9b3b-494b-a53c-45f7a79a45dd", "type": "subtopic", "title": "Ethical organizations", "children": [{"id": "cafd464d-0ead-4f3e-9e6d-8b80f429ff9b", "type": "concept", "title": "Board, executive, staff, volunteer, and constituent roles"}, {"id": "df6d151d-038f-40aa-a8b6-0a48f1c90917", "type": "concept", "title": "Whistleblowing, grievance, transparency, and conflicts"}, {"id": "7e5b50a3-ca21-47f1-8b53-63ccabb9accd", "type": "concept", "title": "Burnout, secondary trauma, psychological safety, and self-care systems"}], "description": "Students examine accountability and worker/client well-being."}]}, {"id": "5af5aff6-6a61-4df0-a5ca-b8bc6b540ba1", "type": "topic", "title": "Organizational Change and Implementation", "description": "Plan and support change while recognizing resistance, power, capacity, and unintended consequences.", "children": [{"id": "8c3514ad-1ef0-496f-928d-1d5380bdc476", "type": "subtopic", "title": "Change diagnosis", "children": [{"id": "410b83c4-8990-47f2-bbf0-143140b207ac", "type": "concept", "title": "Drivers, barriers, readiness, and stakeholder impact"}, {"id": "dfcd5744-0e6b-4fb1-ac6c-d2e680a048e8", "type": "concept", "title": "Technical versus adaptive challenges"}, {"id": "9e814440-ee38-455f-ace3-98ba4b19e400", "type": "concept", "title": "History of change and trust"}], "description": "Students identify why change is needed and what maintains the status quo."}, {"id": "5689d541-b3be-401e-b585-c6138dd8deb6", "type": "subtopic", "title": "Change strategy", "children": [{"id": "9600568a-7b43-4c40-942b-5a411d577575", "type": "concept", "title": "Vision, coalition, communication, and quick wins"}, {"id": "7fcc16a1-ec1e-46fb-8011-ce89e717a0ca", "type": "concept", "title": "Training, workflow redesign, policy, incentives, and technology"}, {"id": "df36cfcc-cb48-48f2-8791-0cc300c44165", "type": "concept", "title": "Implementation teams, champions, and feedback"}], "description": "The goal is participation, clarity, capacity, and credible sequencing."}, {"id": "e3b9f5ce-b7ec-4c2b-9448-5d668ad826da", "type": "subtopic", "title": "Sustaining change", "children": [{"id": "03515ba2-65f0-4a6a-b9b3-a33e6a48ab16", "type": "concept", "title": "Fidelity, adaptation, reach, and staff/constituent experience"}, {"id": "94525ea6-04b0-4127-94ec-aba14fee9fd9", "type": "concept", "title": "Data review and rapid-cycle improvement"}, {"id": "9524ec84-d411-446c-847c-4fe563289a9e", "type": "concept", "title": "Leadership turnover, resources, and policy embedding"}], "description": "Students monitor adoption and institutionalization."}]}, {"id": "ed2191b5-e6d9-4de9-b939-fce236022dab", "type": "topic", "title": "Nonprofit Management, Budgeting, and Resource Development", "description": "Understand the operational foundations that enable mission-driven, accountable organizations.", "children": [{"id": "04503ac9-cce8-4fab-8cb3-aef01de70055", "type": "subtopic", "title": "Financial literacy", "children": [{"id": "64e5bc1f-cf7f-4317-85a2-50a60fbee297", "type": "concept", "title": "Revenue, expense, restricted/unrestricted funds, and cash flow"}, {"id": "e59bad6c-4d75-47d1-8e6f-45fceca12cba", "type": "concept", "title": "Program, operating, and grant budgets"}, {"id": "06ac2c9b-32d6-4b25-b8f5-f1726eeff5b2", "type": "concept", "title": "Internal controls, audits, and financial risk"}], "description": "Students read basic budgets and connect money to mission."}, {"id": "3f1898bf-4868-4f23-a18a-e6384979ba09", "type": "subtopic", "title": "Resource development", "children": [{"id": "ec968d2c-1740-411f-97dc-c551ab5e8f8b", "type": "concept", "title": "Grants, government contracts, philanthropy, fees, events, and earned income"}, {"id": "9d6d4ebb-56e4-46f3-9aa7-6e0cf212f8d1", "type": "concept", "title": "Case for support, prospecting, proposal, and stewardship"}, {"id": "282c9dcc-af24-4616-8ce0-958f4115fc35", "type": "concept", "title": "Fundraising ethics, donor influence, and community accountability"}], "description": "The point is diversified, ethical support."}, {"id": "fb8a1e35-c509-4654-ac7f-c8ca5c75b347", "type": "subtopic", "title": "Operations and people", "children": [{"id": "ce669acf-14d4-4fdd-95a8-91eb2f342323", "type": "concept", "title": "Human resources, volunteers, supervision, and labor considerations"}, {"id": "f88103d6-fc12-4474-95a6-9d7f65eb6db8", "type": "concept", "title": "Procurement, facilities, insurance, safety, and data systems"}, {"id": "b59de705-2d80-41d9-b51c-2b4015546a14", "type": "concept", "title": "Compliance, records, privacy, and continuity"}], "description": "Students recognize management responsibilities."}]}, {"id": "251e8fce-db83-4e6b-8bb3-1a69f0425f97", "type": "topic", "title": "Leadership, Facilitation, and Supervision", "description": "Practice leadership as shared, ethical influence that develops people, supports decisions, and protects mission.", "children": [{"id": "d818db99-a263-4369-9520-f67b5f2bd1bc", "type": "subtopic", "title": "Leadership approaches", "children": [{"id": "268adf98-9ef1-4692-99a9-744c307f4328", "type": "concept", "title": "Adaptive, transformational, servant, distributed, and situational concepts"}, {"id": "dc59cb56-327b-410a-976d-8996012802a6", "type": "concept", "title": "Emotional intelligence and use of self"}, {"id": "ba8ca358-adbb-4716-b8dd-ef64c3eee9c0", "type": "concept", "title": "Power sharing and constituent leadership"}], "description": "Students distinguish authority from leadership."}, {"id": "2ac8a9e7-1a52-4a7a-8210-000b08bdc7ed", "type": "subtopic", "title": "Meetings and facilitation", "children": [{"id": "1e0a0acd-badb-4607-8699-3a52b8c38ff6", "type": "concept", "title": "Purpose, agenda, norms, roles, and decisions"}, {"id": "b5acb110-e34a-438b-bea3-f4613881f614", "type": "concept", "title": "Participation, accessibility, language, conflict, and difficult dynamics"}, {"id": "3cebc8d1-d1ca-4ad9-ba8b-eb40c3d84241", "type": "concept", "title": "Documentation, action tracking, and evaluation"}], "description": "The goal is inclusive, productive group process."}, {"id": "bc4887a5-789d-421d-8f32-59d4e0513692", "type": "subtopic", "title": "Supervision and development", "children": [{"id": "cd36962a-db60-4acf-942e-fc666429aaea", "type": "concept", "title": "Clear expectations and feedback"}, {"id": "73d1dc17-20de-4a79-9d1f-b104d32eccb3", "type": "concept", "title": "Coaching, delegation, performance, and accountability"}, {"id": "7b00c982-cdc5-41d5-b1dd-85447ea8a07a", "type": "concept", "title": "Burnout prevention, boundaries, and referral for support"}], "description": "Students understand foundational administrative, educational, and supportive functions."}]}, {"id": "5a83e376-f0d5-41f0-aa17-8b41532e6263", "type": "topic", "title": "Evaluation, Data, and Learning for Macro Practice", "description": "Use proportionate, ethical evaluation to improve community and organizational work and demonstrate accountability.", "children": [{"id": "ae6245d6-cfd0-47ab-ab2f-b5a01aa70a82", "type": "subtopic", "title": "Evaluation questions and design", "children": [{"id": "4149c126-cac8-464c-b483-6b32dbcf2394", "type": "concept", "title": "Process, outcome, impact, developmental, and participatory evaluation"}, {"id": "c89bc880-3391-44de-93df-25e1d220aaed", "type": "concept", "title": "Baseline, comparison, contribution, and causal limits"}, {"id": "a0cd2dc2-610c-4a56-b68f-6aa170ac1525", "type": "concept", "title": "Qualitative, quantitative, and mixed methods"}], "description": "Students match methods to decisions and stakeholder needs."}, {"id": "0b669327-07bd-4632-bc56-c8558902b133", "type": "subtopic", "title": "Measures and data practice", "children": [{"id": "6ea275cd-6fd5-4b0c-908c-2e409eee8d61", "type": "concept", "title": "Indicators, disaggregation, dashboards, and stories"}, {"id": "7a78d9a8-64a4-45e3-9975-244d9d2d60e8", "type": "concept", "title": "Data quality, privacy, consent, ownership, and bias"}, {"id": "7a566d93-640b-4bd3-a77d-3930e8c0e10f", "type": "concept", "title": "Community interpretation and accessible reporting"}], "description": "The point is useful information without extractive burden."}, {"id": "29508686-362d-4716-8bd1-80018cf8446d", "type": "subtopic", "title": "Learning and action", "children": [{"id": "cd11d59a-b0e3-4da3-807d-45e9f907fc18", "type": "concept", "title": "Sensemaking sessions and recommendations"}, {"id": "c1b408e5-e9a8-46d7-940c-aa1b5304a64d", "type": "concept", "title": "Pause, pivot, scale, sustain, or stop decisions"}, {"id": "3ecbd4cb-cfee-47fc-9eeb-a68f9a6394e8", "type": "concept", "title": "Knowledge sharing and accountability to participants"}], "description": "Students connect findings to adaptation rather than shelf reports."}]}, {"id": "9be5adea-4c24-4e80-a9e4-11e3ff4bd813", "type": "topic", "title": "Strategic Communication and Digital Macro Practice", "description": "Communicate complex issues clearly, mobilize participation, and use digital tools responsibly.", "children": [{"id": "cfd31b04-0525-4178-950e-e8aded6f38c7", "type": "subtopic", "title": "Audience and message", "children": [{"id": "57d904fc-715b-4217-9818-20b13c5f0758", "type": "concept", "title": "Stakeholder/audience analysis"}, {"id": "35a3ca42-086d-4664-ab83-a577b22d695d", "type": "concept", "title": "Problem, values, evidence, story, solution, and ask"}, {"id": "98eefe87-9e4a-4b24-9694-1647b7f96c9c", "type": "concept", "title": "Messengers, framing, and counter-framing"}], "description": "Students build communications around purpose and action."}, {"id": "277245a0-f761-4bc9-ab3b-7e6bdbd2dbef", "type": "subtopic", "title": "Communication products", "children": [{"id": "9c292801-b66b-4cfa-bda9-c5e35db15fea", "type": "concept", "title": "Briefs, memos, testimony, reports, presentations, and infographics"}, {"id": "f3f17c73-19bd-4d57-a88c-62add1bdf26f", "type": "concept", "title": "Media interviews, op-eds, newsletters, and social platforms"}, {"id": "22b5dd3c-d41a-4940-9f3f-4f9b7cf3c03e", "type": "concept", "title": "Plain language, translation, captions, alt text, and visual accessibility"}], "description": "The goal is concise, accessible material for varied settings."}, {"id": "0a13c485-9901-4059-9b6c-f7ad274b1b78", "type": "subtopic", "title": "Digital ethics and security", "children": [{"id": "15ade493-e7a1-4110-949a-ffa938316d7c", "type": "concept", "title": "Digital divide and platform bias"}, {"id": "24cd3b0d-389d-4c98-8d92-98ab2e4ed01c", "type": "concept", "title": "Doxxing, surveillance, harassment, and safety planning"}, {"id": "22145a97-1692-44ef-9d17-77497a05105d", "type": "concept", "title": "Data minimization, account security, archives, and boundaries"}], "description": "Students manage privacy, consent, misinformation, and risk."}]}, {"id": "40b1dc95-b020-4701-a0c9-b2048f1dd98a", "type": "topic", "title": "Integrated Community–Organization Change Project", "description": "Synthesize engagement, assessment, organizing, program/policy design, organizational strategy, and evaluation in a community-accountable project.", "children": [{"id": "34a85cbd-7b99-46b9-9e0c-255e2162c1ce", "type": "subtopic", "title": "Project partnership", "children": [{"id": "4fbfec3f-157d-4ac6-8e25-6996e970a91a", "type": "concept", "title": "Partner-defined question and deliverable"}, {"id": "edef1485-c84c-4a2a-8c84-1b0f63ed389e", "type": "concept", "title": "Roles, consent, confidentiality, timeline, and communication"}, {"id": "72600695-6bbf-4d3e-8e65-f81486df8274", "type": "concept", "title": "Benefits, burdens, compensation, and ownership"}], "description": "Students establish a feasible scope and reciprocal relationship."}, {"id": "e6fe1b1b-c3d0-4641-bf01-40b074486c72", "type": "subtopic", "title": "Analysis and intervention", "children": [{"id": "17fd7272-7ed8-4f99-9d01-494bacbce614", "type": "concept", "title": "Community/organizational assessment"}, {"id": "3a33ba54-cbc3-446c-9abf-ceceb650183e", "type": "concept", "title": "Stakeholder, systems, policy, and equity analysis"}, {"id": "40b2a09e-eb45-4011-b277-bf1588d7e96b", "type": "concept", "title": "Alternatives, implementation, budget, risk, and evaluation"}], "description": "The point is an evidence-informed, power-aware recommendation."}, {"id": "be69e138-a821-4f01-b5ba-a90fdfcbfda0", "type": "subtopic", "title": "Handoff and reflection", "children": [{"id": "f05937c9-d982-4eb3-a796-11954bfd3922", "type": "concept", "title": "Accessible presentation and editable materials"}, {"id": "b22a5dd3-fbab-4ad2-9b90-228e940916e3", "type": "concept", "title": "Partner feedback, revisions, and sustainability"}, {"id": "08eec7bf-85fa-40aa-8f8a-6be4855c3e48", "type": "concept", "title": "Ethical reflection, limitations, and professional learning"}], "description": "Students return useful products and account for their practice."}]}], "dbBacked": true}$swcojson$::jsonb,
