update public.learning_paths
set
  title = 'Social Work Practice with Communities and Organizations',
  goal = 'Social Work Practice with Communities and Organizations',
  summary = 'This course prepares BSW students for ethical, justice-centered generalist practice with communities and organizations. Students learn to engage constituencies, assess assets and power, organize collective action, build coalitions, analyze policy, develop programs, understand organizations, support change, manage resources, evaluate results, and communicate strategically. A community-engaged project integrates the full macro-practice cycle.',
  data = $swcojson${"slug": "social-work-practice-with-communities-and-organizations", "title": "Social Work Practice with Communities and Organizations", "description": "This course prepares BSW students for ethical, justice-centered generalist practice with communities and organizations. Students learn to engage constituencies, assess assets and power, organize collective action, build coalitions, analyze policy, develop programs, understand organizations, support change, manage resources, evaluate results, and communicate strategically. A community-engaged project integrates the full macro-practice cycle.", "topics": [{"id": "2a5db04c-9264-4e1b-a43a-818618b19e6c", "type": "topic", "title": "Macro Social Work and Generalist Practice", "description": "Locate community and organizational change within generalist social work and connect macro conditions to individual and family well-being.", "children": [{"id": "fb82dcbe-b074-46d7-ac40-b39612eb7941", "type": "subtopic", "title": "Levels and integration", "children": [{"id": "2f91efe8-0603-4768-80c0-7c2b82c6dc9b", "type": "concept", "title": "Person-in-environment and ecosystems perspectives"}, {"id": "82b5b62c-70bd-42be-a804-a5260b1c4c44", "type": "concept", "title": "Direct-service patterns as organizational/policy evidence"}, {"id": "b7f0180e-9de9-4935-a28d-9a77891a92d6", "type": "concept", "title": "Case-to-cause and cause-to-case thinking"}], "description": "Students see micro, mezzo, and macro practice as mutually shaping."}, {"id": "11a7edd3-3839-4b0c-9339-8398cf7277de", "type": "subtopic", "title": "Macro practitioner roles", "children": [{"id": "f521b7da-8e41-4ba0-b165-f1eae6eb7fe8", "type": "concept", "title": "Organizer, planner, administrator, advocate, evaluator, policy practitioner"}, {"id": "78aa2fbb-d1aa-4c29-9bda-57a415143d51", "type": "concept", "title": "Facilitator, coalition builder, fundraiser, communicator, and leader"}, {"id": "a95e3916-3f0b-40ef-a872-bf7665c464be", "type": "concept", "title": 