 [{"id": "c4684089-3d74-4560-8ebb-fb799312aa9f", "type": "concept", "title": "Issue cutting, targets, demands, and power analysis"}, {"id": "62a3dc42-b1c2-43fd-a19a-df519d2d4ce3", "type": "concept", "title": "Goals, tactics, timeline, and escalation"}, {"id": "f536779c-2f24-4017-8146-5ca5b7c62e9c", "type": "concept", "title": "Leadership ladder and member ownership"}], "description": "The point is converting a broad concern into a winnable step toward structural change."}, {"id": "4a5ef41b-ae9e-4184-afe2-9c6d145ddf17", "type": "subtopic", "title": "Action and learning", "children": [{"id": "fd68b337-a54e-459b-9bc5-56d8b2e0bcab", "type": "concept", "title": "Meetings, turnout, petitions, direct action, and negotiation"}, {"id": "925d40a5-4b72-4f5b-a1ba-2464969d4472", "type": "concept", "title": "Legal/safety planning and de-escalation"}, {"id": "166dd536-38fd-460a-b3cd-ff7f6bf37a43", "type": "concept", "title": "Debrief, evaluation, celebration, and next cycle"}], "description": "Students prepare ethical, disciplined collective action."}]}, {"id": "cb8ddd96-59b6-4072-922d-eaa32142386b", "type": "topic", "title": "Community Development and Place-Based Practice", "description": "Strengthen community capacity, assets, institutions, opportunity, and control over development.", "children": [{"id": "45d15157-0d8d-4aa4-8d17-bd9a27696358", "type": "subtopic", "title": "Asset-based development", "children": [{"id": "71e8befc-d941-4f46-b70d-0a1ff39fe531", "type": "concept", "title": "Individual, association, institution, physical, cultural, and economic assets"}, {"id": "27958a0e-8db8-4af2-a3cb-cc269b6640bf", "type": "concept", "title": "Resident leadership and mutual aid"}, {"id": "2653ba7a-5584-47e3-b124-f9823f587307", "type": "concept", "title": "Capacity building and local ownership"}], "description": "Students identify capacities without denying structural deprivation."}, {"id": "9bdf81ff-0028-4453-baa3-1940e72cf517", "type": "subtopic", "title": "Place and economic development", "children": [{"id": "c043bd74-44a2-427a-ac3e-a59823556296", "type": "concept", "title": "Housing, land use, transport, food, schools, health, and public space"}, {"id": "a6cb27d9-4efe-4bf8-9915-ea4362ee97e2", "type": "concept", "title": "Workforce, small business, cooperatives, and community wealth"}, {"id": "5bfabbfe-274f-4ed7-9eab-04c9a18677e6", "type": "concept", "title": "Gentrification, displacement, and community benefits"}], "description": "The goal is equitable improvement rather than displacement."}, {"id": "2f59f0eb-f473-4b54-9242-4f8383420aed", "type": "subtopic", "title": "Sustainability and resilience", "children": [{"id": "dbef8e41-f471-46b8-bebe-0586b4e1e64b", "type": "concept", "title": "Climate adaptation and environmental health"}, {"id": "bbd5ec60-61bf-4154-ad3c-7a433038abf0", "type": "concept", "title": "Disaster preparedness, recovery, and mutual aid"}, {"id": "855ff927-e26d-403b-aa6d-17a300d6d7e7", "type": "concept", "title": "Institutionalization without loss of community control"}], "description": "Students plan for shocks and long-term stewardship."}]}, {"id": "4018d9d0-7bfd-439a-84fd-94c94b4473cf", "type": "topic", "title": "Coalition Building and Collaborative Governance", "description": "Create and sustain cross-sector coalitions with shared purpose, equitable governance, and measurable action.", "children": [{"id": "94c051c5-64c9-4087-ae7b-81609b42d85b", "type": "subtopic", "title": "Coalition formation", "children": [{"id": "ea485864-a067-4989-86cf-e2cbcdec0908", "type": "concept", "title": "Issue fit, membership, readiness, and convening"}, {"id": "bb328a76-18c4-4e11-b197-910ce527c6f1", "type": "concept", "title": "Common agenda and theory of change"}, {"id": "663db4ce-f331-4043-98f9-c0356fc49088", "type": "concept", "title": "Member value proposition and resource commitments"}], "description": "Students assess whether collaboration adds value."}, {"id": "2eac3abe-608a-474b-b92b-6a61404654ca", "type": "subtopic", "title": "Governance and participation", "children": [{"id": "8775a402-e7f8-42fa-a315-28d5802fe625", "type": "concept", "title": "Roles, committees, facilitation, voting/consensus, and conflict processes"}, {"id": "0244c0d8-3b25-458e-95d6-4039053bf459", "type": "concept", "title": "Representation, compensation, accessibility, and language justice"}, {"id": "d731c5e0-eb09-4b77-8e80-499e348a7c63", "type": "concept", "title": "Backbone support and distributed leadership"}], "description": "The point is clear, fair decision making."}, {"id": "e4241630-9710-4744-8711-da9e88542869", "type": "subtopic", "title": "Performance and sustainability", "children": [{"id": "0260e688-f030-446d-bdde-3c466b7a8268", "type": "concept", "title": "Participation, trust, implementation, outcomes, and equity"}, {"id": "f62d430f-56f6-47d3-9fe7-777a4fceaf4b", "type": "concept", "title": "Communication and accountability to constituencies"}, {"id": "0da2e071-1437-4241-94fb-8084b731555f", "type": "concept", "title": "Funding, succession, adaptation, and responsible closure"}], "description": "Students track both relationships and results."}]}, {"id": "08a4cff5-573b-461d-8296-6ebbeef74ed1", "type": "topic", "title": "Advocacy, Campaigns, and Civic Participation", "description": "Influence public attitudes, administrative decisions, budgets, policies, and institutional practices through ethical advocacy.", "children": [{"id": "a791a54a-cd37-4833-81fe-1dcf94153cc8", "type": "subtopic", "title": "Advocacy strategy", "children": [{"id": "839fe73e-fb13-4481-a293-de44c775311f", "type": "concept", "title": "Legislative, regulatory, budget, legal, electoral, and organizational venues"}, {"id": "563c9edc-de40-47f7-9b69-6d3c7cfd4d05", "type": "concept", "title": "Insider/outsider and grasstops/grassroots tactics"}, {"id": "d8e34885-ec8b-4de5-8b60-f3ef8ca2f8fc", "type": "concept", "title": "Power, timing, opposition, and coalition alignment"}], "description": "Students specify the decision, target, constituency, and theory of influence."}, {"id": "67af90a5-3ad5-4aea-b999-6371c2d7eb89", "type": "subtopic", "title": "Tactics and communication", "children": [{"id": "021fd630-a70d-4dca-b879-95732605ac65", "type": "concept", "title": "Meetings, testimony, comments, letters, petitions, scorecards, and media"}, {"id": "f5c62333-8385-4843-bff4-9e1c8f84501e", "type": "concept", "title": "Story, evidence, values, messenger, and ask"}, {"id": "29784762-f740-4e0c-9379-fc19b1b23d99", "type": "concept", "title": "Digital organizing, accessibility, and misinformation response"}], "description": "The goal is action matched to context."}, {"id": "3b5b5ae0-0f1d-49b8-954a-c0a3cd8231ec", "type": "subtopic", "title": "Civic participation", "children": [{"id": "80a05b4c-6731-478e-bd64-89b78d2552b9", "type": "concept", "title": "Voter education/engagement within legal and ethical boundaries"}, {"id": "1f1051da-95c2-4f70-8266-f9cad556f73a", "type": "concept", "title": "Participatory budgeting and public hearings"}, {"id": "2cdd47dd-e5dc-4e64-9224-fa96779a77da", "type": "concept", "title": "Boards, commissions, advisory councils, and community oversight"}], "description": "Students expand meaningful democratic involvement."}]}, {"id": "ab316519-0c18-4304-acb1-9e4eaa6d3a4a", "type": "topic", "title": "Policy Practice and Structural Change", "description": "Analyze how policy creates community conditions and develop feasible, justice-centered policy alternatives.", "children": [{"id": "e551eb1f-662a-440c-9ef7-1942bed69e65", "type": "subtopic", "title": "Policy analysis", "children": [{"id": "3078d4ab-6755-41b5-8380-fd26b2dbaf0a", "type": "concept", "title": "Problem definition, history, eligibility, benefits, administration, and financing"}, {"id": "c1a9b760-fae6-499a-9bcb-60fecec770c3", "type": "concept", "title": "Winners, losers, administrative burden, and unintended effects"}, {"id": "144cafed-2c99-403e-b470-cb0edf294ed2", "type": "concept", "title": "Evidence, equity, rights, feasibility, and implementation"}], "description": "Students connect policy design to lived experience and service access."}, {"id": "508ed5e0-59b1-417a-a0c1-720d9806295e", "type": "subtopic", "title": "Policy formulation", "children": [{"id": "4a176cd4-d6dc-410d-bdc4-ce2dc0e24122", "type": "concept", "title": "Goals, options, instruments, and criteria"}, {"id": "8dabbee0-704b-425d-8541-5eedd5202b94", "type": "concept", "title": "Universal, targeted, and targeted-universal approaches"}, {"id": "de05fe65-051e-4126-b6c6-2ca43123cf7f", "type": "concept", "title": "Drafting recommendations and implementation provisions"}], "description": "The point is moving from critique to alternatives."}, {"id": "47164516-e7c3-46fc-9052-40220ccf3708", "type": "subtopic", "title": "Policy advocacy and feedback", "children": [{"id": "c30b7f49-58b4-4940-bfa1-1af6cbfd93a0", "type": "concept", "title": "Coalition and decision-maker strategy"}, {"id": "e3cbe444-9e77-4d7e-b6fd-3d166c2bdba6", "type": "concept", "title": "Rulemaking, budgets, and oversight"}, {"id": "09b563a2-004d-4b9e-b2ab-64b438342cb3", "type": "concept", "title": "Policy surveillance and community feedback"}], "description": "Students monitor adoption, implementation, and adaptation."}]}, {"id": "b7d4003e-0d56-40fa-884b-516efd727dce", "type": "topic", "title": "Program Development and Theory of Change", "description": "Design programs with communities by connecting needs and assets to mechanisms, activities, outcomes, and implementation realities.", "children": [{"id": "ea82e52d-4339-4da2-b765-4662093f77cb", "type": "subtopic", "title": "Co-design and program logic", "children": [{"id": "9fffc485-2d36-4622-93aa-186f4cdc386c", "type": "concept", "title": "Goals, population, eligibility, setting, and access"}, {"id": "aad765a4-2e51-464f-964b-d3bd79af156b", "type": "concept", "title": "Theory of change, logic model, assumptions, and context"}, {"id": "29c8df50-6eeb-48ed-a438-70aa830a09ed", "type": "concept", "title": "Evidence-informed components and cultural adaptation"}], "description": "Students define the problem and solution with intended participants."}, {"id": "2b64c11e-17b0-4f1f-a77a-0f16c4194c3c", "type": "subtopic", "title": "Implementation planning", "children": [{"id": "8c77d522-8442-4cf3-8ff1-7fe2927cd96e", "type": "concept", "title": "Workflow, staffing, partnerships, facilities, data, and technology"}, {"id": "d9c50825-4f95-45d7-a285-7537355f09e1", "type": "concept", "title": "Recruitment, retention, dosage, fidelity, and adaptation"}, {"id": "35b121eb-5a05-42c6-82a9-267deb560bba", "type": "concept", "title": "Risk, accessibility, safeguarding, and contingency"}], "description": "The goal is an operable service, not a paper program."}, {"id": "ee8ad7b1-fc40-4be4-a802-8c5dee1d54b9", "type": "subtopic", "title": "Learning plan", "children": [{"id": "c0d6a66a-33ba-4aca-9a06-2cd313041f3d", "type": "concept", "title": "Process, outcome, equity, and balancing measures"}, {"id": "5c862696-a99f-4746-84c6-7e31adeccf6b", "type": "concept", "title": "Feedback loops and improvement cycles"}, {"id": "2c940263-ad1d-482a-b894-7305b169a1e9", "type": "concept", "title": "Scale, sustainability, and exit criteria"}], "description": "Students specify how success and unintended effects will be known."}]}, {"id": "d9a0a70d-ffab-4617-bb2f-f0d1d2f8e5d6", "type": "topic", "title": "Organizational Theory, Culture, and Assessment", "description": "Understand human-service organizations as open systems shaped by mission, culture, power, environment, and resource dependence.", "children": [{"id": "9660eeb9-5216-48f2-95fe-9fc704592771", "type": "subtopic", "title": "Organizational lenses", "children": [{"id": "40860aef-c575-4685-8a36-15c1e064cc93", "type": "concept", "title": "Formal structure and informal practice"}, {"id": "6818a032-013b-483f-b667-7770e625373c", "type": "concept", "title": "Culture, climate, routines, and symbols"}, {"id": "77cae0e6-b895-4ed5-b1a9-2f875478ced0", "type": "concept", "title": "Environment, legitimacy, and resource dependence"}], "description": "Students compare bureaucratic, human-relations, political, institutional, and systems perspectives."}, {"id": "199e505f-6e0b-4159-bd5d-44332ec698d9", "type": "subtopic", "title": "Organizational assessment", "children": [{"id": "94700b1a-1c6f-48dc-921c-19a1d6683a02", "type": "concept", "title": "Mission, strategy, governance, services, workforce, finance, data, and partnerships"}, {"id": "9d587d52-fa19-47c3-a7e1-79d888d42e1d", "type": "concept", "title": "Stakeholder experience and service journey"}, {"id": "1b1d2d79-b7fd-457b-9957-ae2b918dd031", "type": "concept", "title": "Strengths, gaps, bottlenecks, risk, and equity"}], "description": "The point is a defensible diagnosis before change."}, {"id": "5f86d7e5-9b3b-494b-a53c-45f7a79a45dd", "type": "subtopic", "title": "Ethical organizations", "children": [{"id": "cafd464d-0ead-4f3e-9e6d-8b80f429ff9b", "type": "concept", "title": "Board, executive, staff, volunteer, and constituent roles"}, {"id": "df6d151d-038f-40aa-a8b6-0a48f1c90917", "type": "concept", "title": "Whistleblowing, grievance, transparency, and conflicts"}, {"id": "7e5b50a3-ca21-47f1-8b53-63ccabb9accd", "type": "concept", "title": "Burnout, secondary trauma, psychological safety, and self-care systems"}], "description": "Students examine accountability and worker/client well-being."}]}, {"id": "5af5aff6-6a61-4df0-a5ca-b8bc6b540ba1", "type": "topic", "title": "Organizational Change and Implementation", "description": "Plan and support change while recognizing resistance, power, capacity, and unintended consequences.", "children": [{"id": "8c3514ad-1ef0-496f-928d-1d5380bdc476", "type": "subtopic", "title": "Change diagnosis", "children": [{"id": "410b83c4-8990-47f2-bbf0-143140b207ac", "type": "concept", "title": "Drivers, barriers, readiness, and stakeholder impact"}, {"id": "dfcd5744-0e6b-4fb1-ac6c-d2e680a048e8", "type": "concept", "title": "Technical versus adaptive challenges"}, {"id": "9e814440-ee38-455f-ace3-98ba4b19e400", "type": "concept", "title": "History of change and trust"}], "description": "Students identify why change is needed and what maintains the status quo."}, {"id": "5689d541-b3be-401e-b585-c6138dd8deb6", "type": "subtopic", "title": "Change strategy", "children": [{"id": "9600568a-7b43-4c40-942b-5a411d577575", "type": "concept", "title": "Vision, coalition, communication, and quick wins"}, {"id": "7fcc16a1-ec1e-46fb-8011-ce89e717a0ca", "type": "concept", "title": "Training, workflow redesign, policy, incentives, and technology"}, {"id": "df36cfcc-cb48-48f2-8791-0cc300c44165", "type": "concept", "title": "Implementation teams, champions, and feedback"}], "description": "The goal is participation, clarity, capacity, and credible sequencing."}, {"id": "e3b9f5ce-b7ec-4c2b-9448-5d668ad826da", "type": "subtopic", "title": "Sustaining change", "children": [{"id": "03515ba2-65f0-4a6a-b9b3-a33e6a48ab16", "type": "concept", "title": "Fidelity, adaptation, reach, and staff/constituent experience"}, {"id": "94525ea6-04b0-4127-94ec-aba14fee9fd9", "type": "concept", "title": "Data review and rapid-cycle improvement"}, {"id": "9524ec84-d411-446c-847c-4fe563289a9e", "type": "concept", "title": "Leadership turnover, resources, and policy embedding"}], "description": "Students monitor adoption and institutionalization."}]}, {"id": "ed2191b5-e6d9-4de9-b939-fce236022dab", "type": "topic", "title": "Nonprofit Management, Budgeting, and Resource Development", "description": "Understand the operational foundations that enable mission-driven, accountable organizations.", "children": [{"id": "04503ac9-cce8-4fab-8cb3-aef01de70055", "type": "subtopic", "title": "Financial literacy", "children": [{"id": "64e5bc1f-cf7f-4317-85a2-50a60fbee297", "type": "concept", "title": "Revenue, expense, restricted/unrestricted funds, and cash flow"}, {"id": "e59bad6c-4d75-47d1-8e6f-45fceca12cba", "type": "concept", "title": "Program, operating, and grant budgets"}, {"id": "06ac2c9b-32